Property.Value:
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @id_perfil_default INT = 1;

    IF @username IS NULL OR LTRIM(RTRIM(@username)) = ''
    BEGIN
        THROW 52001, 'El parametro @username es obligatorio.', 1;
    END;

    IF @id_funcionario IS NULL
    BEGIN
        THROW 52002, 'El parametro @id_funcionario es obligatorio.', 1;
    END;

    IF @es_activo NOT IN (0, 1)
    BEGIN
        THROW 52003, 'El parametro @es_activo solo permite 0 o 1.', 1;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM [organizacion].[funcionario]
        WHERE id_funcionario = @id_funcionario
    )
    BEGIN
        THROW 52004, 'El @id_funcionario informado no existe.', 1;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM [auth].[perfil]
        WHERE id_perfil = @id_perfil_default
    )
    BEGIN
        THROW 52005, 'No existe el perfil por defecto configurado en el SP.', 1;
    END;

    BEGIN TRANSACTION;

    SELECT
        @id_usuario = id_usuario
    FROM [auth].[usuario]
    WHERE username = @username;

    IF @id_usuario IS NULL
    BEGIN
        INSERT INTO [auth].[usuario] (
            id_funcionario,
            username,
            activo,
            fecha_creacion,
            auth_provider,
            nombre_mostrar,
            email,
            dominio,
            upn,
            ad_sid,
            fecha_ultimo_acceso
        )
        VALUES (
            @id_funcionario,
            @username,
            @es_activo,
            SYSUTCDATETIME(),
            'AD',
            @nombre_mostrar,
            @email,
            @dominio,
            @upn,
            @ad_sid,
            SYSUTCDATETIME()
        );

        SET @id_usuario = CONVERT(INT, SCOPE_IDENTITY());
    END
    ELSE
    BEGIN
        UPDATE [auth].[usuario]
        SET
            id_funcionario = @id_funcionario,
            activo = @es_activo,
            auth_provider = 'AD',
            nombre_mostrar = @nombre_mostrar,
            email = @email,
            dominio = @dominio,
            upn = @upn,
            ad_sid = @ad_sid,
            fecha_ultimo_acceso = SYSUTCDATETIME()
        WHERE id_usuario = @id_usuario;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM [auth].[usuario_perfil]
        WHERE id_usuario = @id_usuario
          AND id_perfil = @id_perfil_default
    )
    BEGIN
        INSERT INTO [auth].[usuario_perfil] (
            id_usuario,
            id_perfil
        )
        VALUES (
            @id_usuario,
            @id_perfil_default
        );
    END;

    COMMIT TRANSACTION;

    SELECT
        @id_usuario AS id_usuario;
END;

-- =============================================================================
-- SP 6/6 — auth.usp_usuario_upsert_ad
-- =============================================================================
-- Sincroniza los datos de un usuario desde Active Directory hacia la BD.
-- Se ejecuta durante el inicio de sesión. Si el usuario existe, actualiza
-- su fecha_ultimo_acceso y metadatos (UPN, SID, email). Si no existe, lo
-- inserta automáticamente con auth_provider = 'AD'.
-- Retorna el @id_usuario (ya sea el existente o el recién creado).
--
-- IMPORTANTE: el modelo V0002 declara id_funcionario NOT NULL UNIQUE
-- (relación 1:1 con organizacion.funcionario), por lo que @id_funcionario
-- es OBLIGATORIO en este SP.
-- =============================================================================
CREATE   PROCEDURE [auth].[obtener_o_crear_usuario]
    @username          VARCHAR(100),
    @id_funcionario    INT,
    @nombre_mostrar    NVARCHAR(200) = NULL,
    @email             NVARCHAR(256) = NULL,
    @dominio           VARCHAR(64)   = NULL,
    @upn               VARCHAR(256)  = NULL,
    @ad_sid            VARCHAR(128)  = NULL,
    @es_activo         SMALLINT      = 1,
    @id_usuario        INT           OUTPUT
AS

BEGIN
    SET NOCOUNT ON;

    INSERT INTO [auth].[refresh_token]
        (id_usuario, token_hash, fecha_expiracion, ip_creacion, user_agent)
    VALUES
        (@id_usuario, @token_hash, @fecha_expiracion, @ip_creacion, @user_agent);

    SET @id_refresh_token = SCOPE_IDENTITY();
END;

-- =============================================================================
-- SP 1/6 — auth.usp_refresh_token_crear
-- =============================================================================
-- Genera y persiste un nuevo Refresh Token tras un login exitoso.
-- Almacena el hash seguro del token junto con su caducidad y metadatos de
-- auditoría (IP y UserAgent) para trazabilidad de la sesión.
-- Retorna el id_refresh_token autogenerado.
-- =============================================================================
CREATE   PROCEDURE [auth].[usp_refresh_token_crear]
    @id_usuario        INTEGER,
    @token_hash        VARBINARY(32),
    @fecha_expiracion  DATETIME2(0),
    @ip_creacion       VARCHAR(64)    = NULL,
    @user_agent        NVARCHAR(1000) = NULL,
    @id_refresh_token  INTEGER OUTPUT
AS

BEGIN
    SET NOCOUNT ON;
    SET @revocado = 0;

    UPDATE [auth].[refresh_token]
    SET fecha_revocacion = SYSUTCDATETIME()
    WHERE token_hash = @token_hash
      AND fecha_revocacion IS NULL;

    IF (@@ROWCOUNT > 0)
        SET @revocado = 1;
END;

BEGIN
    SET NOCOUNT ON;
    SET @es_valido              = 0;
    SET @id_usuario             = 0;
    SET @id_refresh_token_nuevo = 0;

    DECLARE @id_refresh_token_anterior INTEGER;

    -- Buscar el token vigente
    SELECT TOP (1)
        @id_refresh_token_anterior = rt.id_refresh_token,
        @id_usuario                = rt.id_usuario
    FROM [auth].[refresh_token] rt
    WHERE rt.token_hash = @token_hash_anterior
      AND rt.fecha_revocacion IS NULL
      AND rt.fecha_expiracion > SYSUTCDATETIME();

    IF (@id_refresh_token_anterior IS NULL OR @id_refresh_token_anterior = 0)
        RETURN;

    -- Crear el token nuevo
    INSERT INTO [auth].[refresh_token]
        (id_usuario, token_hash, fecha_expiracion, ip_creacion, user_agent)
    VALUES
        (@id_usuario, @token_hash_nuevo, @fecha_expiracion, @ip_creacion, @user_agent);

    SET @id_refresh_token_nuevo = SCOPE_IDENTITY();

    -- Revocar el anterior y enlazarlo al nuevo
    UPDATE [auth].[refresh_token]
    SET fecha_revocacion           = SYSUTCDATETIME(),
        id_refresh_token_reemplazo = @id_refresh_token_nuevo
    WHERE id_refresh_token = @id_refresh_token_anterior;

    SET @es_valido = 1;
END;

-- =============================================================================
-- SP 5/6 — auth.usp_refresh_token_rotar
-- =============================================================================
-- Ejecuta el mecanismo de Rotación de Tokens (Token Rotation).
-- Al renovar sesión, revoca el token antiguo y emite uno nuevo, creando una
-- cadena de herencia (id_refresh_token_reemplazo). Esto mitiga ataques de
-- robo de tokens (Replay Attacks).
-- @es_valido = 1 si el canje fue exitoso, junto con el id del nuevo token.
-- =============================================================================
CREATE   PROCEDURE [auth].[usp_refresh_token_rotar]
    @token_hash_anterior   VARBINARY(32),
    @token_hash_nuevo      VARBINARY(32),
    @fecha_expiracion      DATETIME2(0),
    @ip_creacion           VARCHAR(64)    = NULL,
    @user_agent            NVARCHAR(1000) = NULL,
    @es_valido             SMALLINT OUTPUT,
    @id_usuario            INTEGER  OUTPUT,
    @id_refresh_token_nuevo INTEGER OUTPUT
AS

BEGIN
    SET NOCOUNT ON;
    SET @es_valido        = 0;
    SET @id_usuario       = 0;
    SET @id_refresh_token = 0;

    SELECT TOP (1)
        @id_refresh_token = rt.id_refresh_token,
        @id_usuario       = rt.id_usuario
    FROM [auth].[refresh_token] rt
    WHERE rt.token_hash = @token_hash
      AND rt.fecha_revocacion IS NULL
      AND rt.fecha_expiracion > SYSUTCDATETIME();

    IF (@id_refresh_token IS NOT NULL AND @id_refresh_token > 0)
        SET @es_valido = 1;
END;

BEGIN
    SET NOCOUNT ON;

    SET @username         = '';
    SET @perfiles_nombres = N'';
    SET @roles_nombres    = N'';
    SET @claims_csv       = '';
    SET @permisos_csv     = '';
    SET @es_activo        = 0;

    -- Identidad y estado
    SELECT
        @username  = u.username,
        @es_activo = u.activo
    FROM [auth].[usuario] u
    WHERE u.id_usuario = @id_usuario;

    IF (@username = '' OR @es_activo = 0)
        RETURN;

    -- Perfiles asignados al usuario
    SELECT @perfiles_nombres = ISNULL(STRING_AGG(p.nombre, N', '), N'')
    FROM [auth].[usuario_perfil] up
    INNER JOIN [auth].[perfil] p ON up.id_perfil = p.id_perfil
    WHERE up.id_usuario = @id_usuario;

    -- Roles únicos a través de los perfiles
    SELECT @roles_nombres = ISNULL(STRING_AGG(rol_nombre, N', '), N'')
    FROM (
        SELECT DISTINCT r.nombre AS rol_nombre
        FROM [auth].[usuario_perfil] up
        INNER JOIN [auth].[perfil_rol] pr ON up.id_perfil = pr.id_perfil
        INNER JOIN [auth].[rol] r ON pr.id_rol = r.id_rol
        WHERE up.id_usuario = @id_usuario
    ) AS roles_unicos;

    -- Claims (claim_code de cada perfil_rol — son los que viajan en el JWT)
    SELECT @claims_csv = ISNULL(STRING_AGG(pr.claim_code, ','), '')
    FROM [auth].[usuario_perfil] up
    INNER JOIN [auth].[perfil_rol] pr ON up.id_perfil = pr.id_perfil
    WHERE up.id_usuario = @id_usuario;

    -- Permisos atómicos únicos (codigo_funcion)
    SELECT @permisos_csv = ISNULL(STRING_AGG(codigo_permiso, ','), '')
    FROM (
        SELECT DISTINCT perm.codigo_funcion AS codigo_permiso
        FROM [auth].[usuario_perfil] up
        INNER JOIN [auth].[perfil_rol] pr ON up.id_perfil = pr.id_perfil
        INNER JOIN [auth].[perfil_rol_permiso] prp ON pr.id_perfil_rol = prp.id_perfil_rol
        INNER JOIN [auth].[permiso] perm ON prp.id_permiso = perm.id_permiso
        WHERE up.id_usuario = @id_usuario
    ) AS permisos_unicos;
END;

-- =============================================================================
-- SP 2/6 — auth.usp_usuario_obtener_claims
-- =============================================================================
-- Extrae la matriz completa de autorización de un usuario específico.
-- Cruza las tablas de perfiles, roles (con su nivel de seguridad) y permisos
-- para concatenarlos en cadenas CSV. Estos strings son los que el backend
-- inyectará como 'Claims' dentro del payload del token JWT.
-- Retorna CSVs con los Claims (ej. POL-IN-3 desde claim_code) y permisos
-- atómicos (ej. O1,D5 desde codigo_funcion).
-- =============================================================================
CREATE   PROCEDURE [auth].[usp_usuario_obtener_claims]
    @id_usuario        INTEGER,
    @username          VARCHAR(100)   OUTPUT,
    @perfiles_nombres  NVARCHAR(MAX)  OUTPUT,
    @roles_nombres     NVARCHAR(MAX)  OUTPUT,
    @claims_csv        VARCHAR(MAX)   OUTPUT,
    @permisos_csv      VARCHAR(MAX)   OUTPUT,
    @es_activo         SMALLINT       OUTPUT
AS

BEGIN
