	DECLARE
		@id_log_guardar_denuncia INT,
		@error NVARCHAR(MAX)
	;

	INSERT INTO denuncias.log_guardar_denuncia
	(
		ts_utc_inicio,
		in_denuncia_json,
		client_net_address,
		[system_user],
		[current_user]
	)
	VALUES
	(
		GETUTCDATE(),
		@in_denuncia_json,
		CAST(CONNECTIONPROPERTY('client_net_address') AS NVARCHAR(100)),
		SYSTEM_USER,
		CURRENT_USER
	)

	SET @id_log_guardar_denuncia = SCOPE_IDENTITY();

	BEGIN TRY
		DECLARE
			@id_denuncia INT,
			@fecha_denuncia DATETIME,
			@id_funcionario INT,
			@id_detalle_lugar_recepcion_denuncia INT,
			@id_organismo_encargado_denuncia INT,
			@id_organismo_fiscalia INT,
			@id_organismo_registro_denuncia INT,
			@id_origen_denuncia INT,
			@puede_reconocer_imputado BIT,
			@teme_por_seguridad BIT,
			@latitud DECIMAL(10, 7),
			@longitud DECIMAL(10, 7),
			@fecha_ocurrencia_desde DATE,
			@fecha_ocurrencia_hasta DATE,
			@hora_ocurrencia_desde TIME(0),
			@hora_ocurrencia_hasta TIME(0),
			@id_clasificacion_delito INT,
			@canal_recepcion NVARCHAR(50),
			@id_estado_denuncia INT
		;

		SELECT
			@id_denuncia = JSON_VALUE(@in_denuncia_json, '$.id_denuncia'),
			@fecha_denuncia = TRY_CONVERT(DATETIME, JSON_VALUE(@in_denuncia_json, '$.fecha_denuncia'), 120),
			@id_funcionario = JSON_VALUE(@in_denuncia_json, '$.id_funcionario'),
			@id_detalle_lugar_recepcion_denuncia = JSON_VALUE(@in_denuncia_json, '$.id_detalle_lugar_recepcion_denuncia'),
			@id_organismo_encargado_denuncia = JSON_VALUE(@in_denuncia_json, '$.id_organismo_encargado_denuncia'),
			@id_organismo_fiscalia = JSON_VALUE(@in_denuncia_json, '$.id_organismo_fiscalia'),
			@id_organismo_registro_denuncia = JSON_VALUE(@in_denuncia_json, '$.id_organismo_registro_denuncia'),
			@id_origen_denuncia = JSON_VALUE(@in_denuncia_json, '$.id_origen_denuncia'),
			@puede_reconocer_imputado = TRY_CONVERT(BIT, JSON_VALUE(@in_denuncia_json, '$.puede_reconocer_imputado')),
			@teme_por_seguridad = TRY_CONVERT(BIT, JSON_VALUE(@in_denuncia_json, '$.teme_por_seguridad')),
			@latitud = TRY_CONVERT(DECIMAL(10,7), JSON_VALUE(@in_denuncia_json, '$.latitud')),
			@longitud = TRY_CONVERT(DECIMAL(10,7), JSON_VALUE(@in_denuncia_json, '$.longitud')),
			@fecha_ocurrencia_desde = TRY_CONVERT(DATE, JSON_VALUE(@in_denuncia_json, '$.fecha_ocurrencia_desde'), 23),
			@fecha_ocurrencia_hasta = TRY_CONVERT(DATE, JSON_VALUE(@in_denuncia_json, '$.fecha_ocurrencia_hasta'), 23),
			@hora_ocurrencia_desde = TRY_CONVERT(TIME(0), JSON_VALUE(@in_denuncia_json, '$.hora_ocurrencia_desde')),
			@hora_ocurrencia_hasta = TRY_CONVERT(TIME(0), JSON_VALUE(@in_denuncia_json, '$.hora_ocurrencia_hasta')),
			@id_clasificacion_delito = JSON_VALUE(@in_denuncia_json, '$.id_clasificacion_delito')
		;

		IF @id_denuncia IS NOT NULL
		BEGIN
			RAISERROR('update denuncia no implementado aun', 16, 1);
		END

		IF @id_funcionario IS NULL
		BEGIN
			RAISERROR('debe especificar un funcionario para registrar la denuncia', 16, 1);
		END

		DECLARE @origen_denuncia TABLE
		(
			id_origen_denuncia INT,
			descripcion NVARCHAR(100)
		)

		INSERT INTO @origen_denuncia
		(
			id_origen_denuncia,
			descripcion
		)
		VALUES
		(1, 'Denuncia web'),
		(2, 'Parte policial'),
		(3, 'Derivación fiscalía'),
		(4, 'Oficio')

		SELECT @canal_recepcion = descripcion
		FROM @origen_denuncia
		WHERE id_origen_denuncia = @id_origen_denuncia

		SELECT @id_estado_denuncia = id_estado_denuncia
		FROM denuncias.cat_estado_denuncia
		WHERE codigo = 'BORRADOR'

		INSERT INTO denuncias.denuncia
		(
			folio,
			fecha_denuncia,
			canal_recepcion,
			id_funcionario_receptor,
			fecha_registro,
			indicador_vif,
			dominio_propiedad,
			es_flagrancia,
			id_estado_denuncia,
			id_detalle_lugar_recepcion_denuncia,
			id_organismo_encargado_denuncia,
			id_organismo_fiscalia,
			id_organismo_registro_denuncia,
			id_origen_denuncia,
			puede_reconocer_imputado,
			teme_por_seguridad
		)
		VALUES
		(
			'0',
			@fecha_denuncia,
			@canal_recepcion,
			@id_funcionario,
			GETUTCDATE(),
			0,
			0,
			0,
			@id_estado_denuncia,
			@id_detalle_lugar_recepcion_denuncia,
			@id_organismo_encargado_denuncia,
			@id_organismo_fiscalia,
			@id_organismo_registro_denuncia,
			@id_origen_denuncia,
			@puede_reconocer_imputado,
			@teme_por_seguridad
		)

		SET @id_denuncia = SCOPE_IDENTITY();

		UPDATE denuncias.denuncia
		SET folio = CAST(@id_denuncia AS NVARCHAR(30))
		WHERE id_denuncia = @id_denuncia

		DECLARE @id_lugar_base INT;

		INSERT INTO ubicacion.lugar_base
		(
			latitud,
			longitud,
			fecha_registro,
			direccion_exacta
		)
		VALUES
		(
			@latitud,
			@longitud,
			GETUTCDATE(),
			1
		)

		SET @id_lugar_base = SCOPE_IDENTITY();

		DECLARE @id_lugar INT;

		INSERT INTO ubicacion.lugar
		(
			id_lugar_base,
			id_tipo_subdivision,
			fecha_registro
		)
		VALUES
		(
			@id_lugar_base,
			1, -- GENERAL
			GETUTCDATE()
		)

		SET @id_lugar = SCOPE_IDENTITY();

		DECLARE @id_hecho INT;

		INSERT INTO investigacion.hecho
		(
			descripcion,
			fecha_ocurrencia_inicio,
			fecha_ocurrencia_fin,
			hora_ocurrencia_inicio,
			hora_ocurrencia_fin
		)
		VALUES
		(
			'descripción del hecho de la denuncia',
			@fecha_ocurrencia_desde,
			@fecha_ocurrencia_hasta,
			@hora_ocurrencia_desde,
			@hora_ocurrencia_hasta
		)

		SET @id_hecho = SCOPE_IDENTITY();

		INSERT INTO denuncias.denuncia_hecho
		(
			id_denuncia,
			id_hecho
		)
		VALUES
		(
			@id_denuncia,
			@id_hecho
		)

		INSERT INTO investigacion.hecho_lugar
		(
			id_hecho,
			id_lugar,
			id_rol_lugar,
			es_principal,
			fecha_registro
		)
		VALUES
		(
			@id_hecho,
			@id_lugar,
			2,
			1,
			GETUTCDATE()
		)

		--INSERT INTO investigacion.protocolo_delito
		--(
		--	id_clasificacion_delito,
		--	nombre,
		--	activo,
		--	fecha_registro
		--)
		--VALUES
		--(
		--	@id_clasificacion_delito,
		--	'nombre del protocolo del delito',
		--	1,
		--	GETUTCDATE()
		--)

		DECLARE @id_delito_imputado INT;

		INSERT INTO investigacion.delito_imputado
		(
			id_hecho,
			id_clasificacion_delito,
			id_grado_ejecucion,
			contexto_vif,
			relato,
			fecha_registro,
			es_delito_principal
		)
		VALUES
		(
			@id_hecho,
			@id_clasificacion_delito,
			2,-- tentativo
			0,
			'',
			GETUTCDATE(),
			1
		)

		SET @id_delito_imputado = SCOPE_IDENTITY();

		UPDATE investigacion.delito_imputado
		SET folio = CAST(id_delito_imputado AS NVARCHAR(100))
		WHERE id_delito_imputado = @id_delito_imputado

		SET @out_resp_json = '{"guardado":true,"id_denuncia":' + CAST(@id_denuncia AS NVARCHAR(100)) + '}';
	END TRY
	BEGIN CATCH
		SET @error = ERROR_PROCEDURE() + ': línea ' + CAST(ERROR_LINE() AS NVARCHAR(100)) + ', error: ' + ERROR_MESSAGE();
		SET @out_resp_json = '{"guardado":false,"error":"' + ERROR_MESSAGE() + '"}';
	END CATCH

	UPDATE denuncias.log_guardar_denuncia
	SET ts_utc_fin = GETUTCDATE(),
		out_resp_json = @out_resp_json,
		error = @error
	WHERE id_log_guardar_denuncia = @id_log_guardar_denuncia
END

CREATE PROCEDURE denuncias.guardar_denuncia
	@in_denuncia_json NVARCHAR(MAX),
	@out_resp_json NVARCHAR(MAX) OUT
AS

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_tipo_denuncia,
        codigo,
        descripcion,
        activo
    FROM [denuncias].[cat_tipo_denuncia];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @id_persona IS NULL
    BEGIN
        THROW 51001, 'El parametro @id_persona es obligatorio.', 1;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM [personas].[persona]
        WHERE id_persona = @id_persona
          AND fecha_eliminacion IS NULL
    )
    BEGIN
        THROW 51002, 'No existe una persona activa para el @id_persona informado.', 1;
    END;

    IF @id_unidad IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM [organizacion].[unidad]
            WHERE id_unidad = @id_unidad
       )
    BEGIN
        THROW 51003, 'El @id_unidad informado no existe.', 1;
    END;

    IF @id_cargo_funcion IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM [organizacion].[cat_cargo_funcion]
            WHERE id_cargo_funcion = @id_cargo_funcion
       )
    BEGIN
        THROW 51004, 'El @id_cargo_funcion informado no existe.', 1;
    END;

    SET @id_funcionario = @id_persona;

    IF EXISTS (
        SELECT 1
        FROM [organizacion].[funcionario]
        WHERE id_funcionario = @id_funcionario
    )
    BEGIN
        UPDATE [organizacion].[funcionario]
        SET
            ad_object_id         = @ad_object_id,
            ad_sam_account      = @ad_sam_account,
            ad_email            = @ad_email,
            id_unidad           = @id_unidad,
            id_cargo_funcion    = @id_cargo_funcion,
            numero_placa        = @numero_placa,
            fecha_ultima_sync   = @fecha_ultima_sync,
            sync_estado         = @sync_estado,
            fecha_actualizacion = SYSUTCDATETIME(),
            fecha_eliminacion   = NULL
        WHERE id_funcionario = @id_funcionario;
    END
    ELSE
    BEGIN
        INSERT INTO [organizacion].[funcionario] (
            id_funcionario,
            ad_object_id,
            ad_sam_account,
            ad_email,
            id_unidad,
            id_cargo_funcion,
            numero_placa,
            fecha_ultima_sync,
            sync_estado,
            fecha_registro,
            fecha_actualizacion,
            fecha_eliminacion
        )
        VALUES (
            @id_funcionario,
            @ad_object_id,
            @ad_sam_account,
            @ad_email,
            @id_unidad,
            @id_cargo_funcion,
            @numero_placa,
            @fecha_ultima_sync,
            @sync_estado,
            SYSUTCDATETIME(),
            NULL,
            NULL
        );
    END;

    SELECT
        id_funcionario AS IdFuncionario,
        ad_object_id AS AdObjectId,
        ad_sam_account AS AdSamAccount,
        ad_email AS AdEmail,
        id_unidad AS IdUnidad,
        id_cargo_funcion AS IdCargoFuncion,
        numero_placa AS NumeroPlaca,
        fecha_ultima_sync AS FechaUltimaSync,
        sync_estado AS SyncEstado,
        fecha_registro AS FechaRegistro,
        fecha_actualizacion AS FechaActualizacion,
        fecha_eliminacion AS FechaEliminacion
    FROM [organizacion].[funcionario]
    WHERE id_funcionario = @id_funcionario;
END;

CREATE   PROCEDURE [organizacion].[obtener_o_crear_funcionario]
    @id_persona          INT,
    @ad_object_id        NVARCHAR(36)  = NULL,
    @ad_sam_account      NVARCHAR(50)  = NULL,
    @ad_email            NVARCHAR(200) = NULL,
    @id_unidad           INT           = NULL,
    @id_cargo_funcion    INT           = NULL,
    @numero_placa        NVARCHAR(20)  = NULL,
    @fecha_ultima_sync   DATETIME2     = NULL,
    @sync_estado         NVARCHAR(20)  = NULL,
    @id_funcionario      INT OUTPUT
AS

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_tipo_unidad,
        codigo,
        nombre
    FROM [organizacion].[cat_tipo_unidad];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @id_tipo_documento IS NULL
    BEGIN
        THROW 50001, 'El parametro @id_tipo_documento es obligatorio.', 1;
    END;

    IF @numero_documento IS NULL OR LTRIM(RTRIM(@numero_documento)) = ''
    BEGIN
        THROW 50002, 'El parametro @numero_documento es obligatorio.', 1;
    END;

    IF @es_identificable NOT IN (0, 1)
    BEGIN
        THROW 50003, 'El parametro @es_identificable solo permite 0 o 1.', 1;
    END;

    IF @domicilio_extranjero NOT IN (0, 1)
    BEGIN
        THROW 50004, 'El parametro @domicilio_extranjero solo permite 0 o 1.', 1;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM [personas].[cat_tipo_documento]
        WHERE id_tipo_documento = @id_tipo_documento
    )
    BEGIN
        THROW 50005, 'El @id_tipo_documento informado no existe.', 1;
    END;

    IF @id_pais_emisor IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM [ubicacion].[pais]
            WHERE id_pais = @id_pais_emisor
       )
    BEGIN
        THROW 50006, 'El @id_pais_emisor informado no existe.', 1;
    END;

    IF @id_sexo IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM [personas].[cat_sexo]
            WHERE id_sexo = @id_sexo
       )
    BEGIN
        THROW 50007, 'El @id_sexo informado no existe.', 1;
    END;

    IF @id_genero IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM [personas].[cat_genero]
            WHERE id_genero = @id_genero
       )
    BEGIN
        THROW 50008, 'El @id_genero informado no existe.', 1;
    END;

    IF @id_pais_nacionalidad IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM [ubicacion].[pais]
            WHERE id_pais = @id_pais_nacionalidad
       )
    BEGIN
        THROW 50009, 'El @id_pais_nacionalidad informado no existe.', 1;
    END;

    IF @id_comuna_nacimiento IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
            FROM [ubicacion].[comuna]
            WHERE id_comuna = @id_comuna_nacimiento
       )
    BEGIN
        THROW 50010, 'El @id_comuna_nacimiento informado no existe.', 1;
    END;

    SELECT TOP 1
        @id_persona = i.id_persona
    FROM [personas].[identificacion] i
    WHERE i.id_tipo_documento = @id_tipo_documento
      AND i.numero_documento = @numero_documento
      AND (
            i.id_pais_emisor = @id_pais_emisor
            OR (i.id_pais_emisor IS NULL AND @id_pais_emisor IS NULL)
          )
      AND i.fecha_eliminacion IS NULL;

    IF @id_persona IS NOT NULL
    BEGIN
        SELECT
            @id_persona AS id_persona;

        RETURN;
    END;

    BEGIN TRANSACTION;

    INSERT INTO [personas].[persona] (
        fecha_nacimiento,
        fecha_defuncion,
        id_sexo,
        id_genero,
        id_pais_nacionalidad,
        id_comuna_nacimiento,
        es_identificable,
        domicilio_extranjero,
        fecha_registro,
        fecha_actualizacion,
        fecha_eliminacion
    )
    VALUES (
        @fecha_nacimiento,
        @fecha_defuncion,
        @id_sexo,
        @id_genero,
        @id_pais_nacionalidad,
        @id_comuna_nacimiento,
        @es_identificable,
        @domicilio_extranjero,
        SYSUTCDATETIME(),
        NULL,
        NULL
    );

    SET @id_persona = CONVERT(INT, SCOPE_IDENTITY());

    INSERT INTO [personas].[identificacion] (
        id_persona,
        id_tipo_documento,
        numero_documento,
        digito_verificador,
        id_pais_emisor,
        fecha_emision,
        fecha_vencimiento,
        es_principal,
        fecha_registro,
        fecha_eliminacion,
        es_temporal
    )
    VALUES (
        @id_persona,
        @id_tipo_documento,
        @numero_documento,
        @digito_verificador,
        @id_pais_emisor,
        @fecha_emision,
        @fecha_vencimiento,
        1,
        SYSUTCDATETIME(),
        NULL,
        0
    );

    COMMIT TRANSACTION;

    SELECT
        @id_persona AS id_persona;
END;

CREATE   PROCEDURE [personas].[obtener_o_crear_persona]
    @id_tipo_documento      INT,
    @numero_documento       NVARCHAR(30),
    @digito_verificador     NCHAR(1) = NULL,
    @id_pais_emisor         INT = NULL,
    @fecha_emision          DATE = NULL,
    @fecha_vencimiento      DATE = NULL,

    @fecha_nacimiento       DATE = NULL,
    @fecha_defuncion        DATE = NULL,
    @id_sexo                INT = NULL,
    @id_genero              INT = NULL,
    @id_pais_nacionalidad   INT = NULL,
    @id_comuna_nacimiento   INT = NULL,
    @es_identificable       SMALLINT = 1,
    @domicilio_extranjero   SMALLINT = 0,

    @id_persona             INT OUTPUT
AS

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_nacionalidad,
        descripcion,
        codigo_iso_alpha_3,
        codigo_iso_alpha_2
    FROM [personas].[cat_nacionalidad];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_nivel_escolaridad,
        descripcion,
        orden
    FROM [personas].[cat_nivel_escolaridad];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_ocupacion,
        descripcion,
        codigo_sii
    FROM [personas].[cat_ocupacion];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_sexo,
        descripcion
    FROM [personas].[cat_sexo];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_tipo_documento,
        descripcion
    FROM [personas].[cat_tipo_documento];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_tipo_estado_civil,
        descripcion
    FROM [personas].[cat_tipo_estado_civil];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_rol_lugar,
        codigo,
        nombre
    FROM [ubicacion].[cat_rol_lugar];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_comuna,
        id_provincia,
        descripcion,
        costera
    FROM [ubicacion].[comuna];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_pais,
        descripcion,
        codigo_iso_alpha_3,
        codigo_iso_alpha_2
    FROM [ubicacion].[pais];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_provincia,
        id_region,
        descripcion
    FROM [ubicacion].[provincia];
END;

BEGIN
    SET NOCOUNT ON;

    SELECT
        id_region,
        id_pais,
        descripcion,
        orden
    FROM [ubicacion].[region];
END;
